from __future__ import annotations
from collections import deque

def ancestor_ranks(n: int, edges: list[tuple[int, int]]) -> list[int]:
    out=[[] for _ in range(n)]; indeg=[0]*n
    for u,v in edges: out[u].append(v); indeg[v]+=1
    q=deque(i for i in range(n) if indeg[i]==0); anc=[set() for _ in range(n)]; seen=0
    while q:
        u=q.popleft(); seen+=1
        for v in out[u]:
            anc[v] |= anc[u] | {u}; indeg[v]-=1
            if indeg[v]==0: q.append(v)
    if seen != n: raise ValueError("cycle detected")
    return [len(a) for a in anc]

if __name__ == "__main__":
    diamond=[(0,1),(0,2),(1,3),(2,3)]
    print("diamond ranks:", ancestor_ranks(4,diamond))

from __future__ import annotations

def total_order_edges(n: int) -> list[tuple[int, int]]:
    return [(i,j) for i in range(n) for j in range(i+1,n)]

def robust_after_every_deletion(n: int) -> bool:
    edges=set(total_order_edges(n))
    for deleted in range(n):
        survivors=[v for v in range(n) if v != deleted]
        for i,a in enumerate(survivors):
            for b in survivors[i+1:]:
                if (a,b) not in edges and (b,a) not in edges: return False
    return True

if __name__ == "__main__":
    for n in range(3,11): print(n, robust_after_every_deletion(n))

from __future__ import annotations
from collections import deque

def connected(n: int, edges: list[tuple[int,int]], deleted: int) -> bool:
    alive=[v for v in range(n) if v != deleted]
    if len(alive)<2: return True
    adj=[set() for _ in range(n)]
    for u,v in edges:
        if deleted not in (u,v): adj[u].add(v); adj[v].add(u)
    seen={alive[0]}; q=deque(seen)
    while q:
        u=q.popleft()
        for v in adj[u]-seen: seen.add(v); q.append(v)
    return len(seen)==len(alive)

if __name__ == "__main__":
    n=6; chain=[(i,i+1) for i in range(n-1)]
    total=[(i,j) for i in range(n) for j in range(i+1,n)]
    print("chain:",[connected(n,chain,d) for d in range(n)])
    print("total:",[connected(n,total,d) for d in range(n)])
